(()=>{const form=document.getElementById('profile-form'),steps=[...form.querySelectorAll('fieldset')],markers=[...form.querySelectorAll('.steps li')],prev=document.getElementById('previous'),next=document.getElementById('next'),finish=document.getElementById('finish');let current=0;form.classList.add('enhanced');
function update(){const alias=document.getElementById('apelido').value.trim()||'Seu nome';document.getElementById('public-name').textContent='Em atendimento com '+alias;const preview=document.getElementById('signature-preview');preview.textContent=alias+': Olá! Como posso ajudar?';const color=form.querySelector('input[name=cor_chat]:checked');if(color){preview.style.background=color.dataset.color;preview.style.color=['lavanda','lima','amarelo','coral'].includes(color.value)?'#141B27':'#fff'}form.querySelectorAll('[data-summary]').forEach(el=>el.textContent=document.getElementById(el.dataset.summary).value.trim()||'Não informado')}
function show(){steps.forEach((el,i)=>el.hidden=i!==current);markers.forEach((el,i)=>i===current?el.setAttribute('aria-current','step'):el.removeAttribute('aria-current'));prev.hidden=current===0;next.hidden=current===2;finish.hidden=current!==2;update();steps[current].querySelector('input')?.focus()}
next.addEventListener('click',()=>{for(const input of steps[current].querySelectorAll('input')){if(!input.reportValidity())return}current++;show()});prev.addEventListener('click',()=>{current--;show()});form.addEventListener('input',update);form.addEventListener('submit',e=>{if(current!==2){e.preventDefault();next.click()}});document.getElementById('foto').addEventListener('change',e=>{const file=e.target.files[0],img=document.getElementById('photo-preview');e.target.setCustomValidity('');if(!file){img.hidden=true;return}if(file.size>2097152){e.target.setCustomValidity('A foto deve ter até 2 MB.');e.target.reportValidity();return}e.target.setCustomValidity('');const reader=new FileReader();reader.onload=()=>{img.src=reader.result;img.hidden=false};reader.readAsDataURL(file)});show();})();
</script></body></html>